"""YAML renderer — standard-library only (uses repr-based output)."""

from ._core import PluginError, Renderer, register


def _yaml_scalar(value) -> str:
    """Return a YAML-safe scalar string for *value*."""
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        return repr(value)
    # Treat everything else as a string
    s = str(value)
    # Quote if the value could be misinterpreted
    if s == "" or s in (
        "null", "Null", "NULL",
        "true", "True", "TRUE",
        "false", "False", "FALSE",
        "yes", "Yes", "YES",
        "no", "No", "NO",
        "on", "On", "ON",
        "off", "Off", "OFF",
    ):
        return f'"{s}"'
    # Quote if it starts/ends with whitespace or contains special chars
    if s[0] in (" ", "\t") or s[-1] in (" ", "\t"):
        return f'"{s}"'
    if any(c in s for c in (":", "{", "}", "[", "]", ",", "&", "*", "#", "?", "|", "-", "<", ">", "=", "!", "%", "@", "`")):
        return f'"{s}"'
    return s


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        lines: list[str] = []
        for row in rows:
            lines.append("-")
            for key, value in row.items():
                lines.append(f"  {key}: {_yaml_scalar(value)}")
        return "\n".join(lines) + "\n"

