"""Tiny renderer plugin registry. Standard library only -- see CONTRIBUTING.md."""

__all__ = ["PluginError", "Renderer", "register", "get", "CsvRenderer", "JsonRenderer", "YamlRenderer"]

_REGISTRY: dict[str, type] = {}


class PluginError(Exception):
    """Raised by a renderer for input it cannot render."""


class Renderer:
    """Base renderer. Subclasses implement render(rows) -> str."""

    def render(self, rows: list[dict]) -> str:
        raise NotImplementedError


def register(name: str):
    def deco(cls):
        _REGISTRY[name] = cls
        return cls
    return deco


def get(name: str) -> type:
    _ensure_loaded()
    if name not in _REGISTRY:
        raise PluginError(f"no renderer named {name!r}")
    return _REGISTRY[name]


# Lazy-load renderers to avoid circular-import RuntimeWarning.
_LOADED = False


def _ensure_loaded():
    global _LOADED
    if _LOADED:
        return
    _LOADED = True
    import importlib
    importlib.import_module("plugins.csv_out")
    importlib.import_module("plugins.json_out")
    importlib.import_module("plugins.yaml_out")


def __getattr__(name: str):
    _ensure_loaded()
    _LAZY = {
        "CsvRenderer": "plugins.csv_out",
        "JsonRenderer": "plugins.json_out",
        "YamlRenderer": "plugins.yaml_out",
    }
    if name in _LAZY:
        return getattr(importlib.import_module(_LAZY[name]), name)
    raise AttributeError(f"module {__name__!r} has no attribute {name!r}")

